{
  "summary": "The function fn_02 computes a CRC-32 checksum.",
  "proposed_name": "fn_02",
  "algorithm": "ALG: CRC-32",
  "self_confidence": 1.0,
  "claims": [
    {
      "id": "1",
      "type": "ALG",
      "text": "Implements CRC-32.",
      "asserted_values": [],
      "confidence": 1.0
    },
    {
      "id": "2",
      "type": "CONST",
      "text": "Initial CRC-32 value uses the constant 0xcbf29ce484222325.",
      "asserted_values": ["cbf29ce484222325"],
      "confidence": 1.0
    },
    {
      "id": "3",
      "type": "IO",
      "text": "Returns 0xcbf29ce484222325 when len == 0.",
      "asserted_values": ["cbf29ce484222325"],
      "confidence": 1.0,
      "io": {
        "when": "len == 0",
        "returns": "cbf29ce484222325"
      }
    },
    {
      "id": "4",
      "type": "IO",
      "text": "Returns the computed CRC-32 value when len > 0.",
      "asserted_values": [],
      "confidence": 1.0,
      "io": {
        "when": "len > 0",
        "returns": "computed CRC-32 value"
      }
    },
    {
      "id": "5",
      "type": "SIDE",
      "text": "Does not write to out.",
      "asserted_values": [],
      "confidence": 1.0
    },
    {
      "id": "6",
      "type": "CF",
      "text": "Iterates over each byte in the input buffer.",
      "asserted_values": [],
      "confidence": 1.0
    }
  ],
  "recovered_c": "uint64_t fn_02(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  uint64_t crc = 0xcbf29ce484222325;\n  if (len != 0) {\n    for (size_t i = 0; i < len; i++) {\n      crc = (crc ^ in[i]) * 0x100000001b3;\n    }\n  }\n  return crc;\n}"
}
